async function dropItemByName(name: string) {
  const item = sdk.findInventoryItem(new RegExp(name, 'i'));
  if (!item) return false;
  // Try various drop option indices (5, 7, 8)
  for (const opIdx of [5, 7, 8]) {
    const r = await sdk.sendUseItem(item.slot, opIdx);
    if (r.success) return true;
  }
  return false;
}

async function getInventoryCount(name: string): Promise<number> {
  const inv = sdk.getInventory();
  return inv.filter(i => i.name.toLowerCase().includes(name.toLowerCase())).reduce((sum, i) => sum + i.count, 0);
}

async function getEmptySlots(): Promise<number> {
  return 28 - sdk.getInventory().length;
}

