// Long-running HP training loop - 25 minutes
const startXp = sdk.getState().skills?.find(s => s.name === 'Hitpoints')?.experience ?? 0;
const startTime = Date.now();
let kills = 0;

console.log(`Starting HP XP: ${startXp}`);

const MAX_RUNTIME_MS = 25 * 60 * 1000;

while (Date.now() - startTime < MAX_RUNTIME_MS) {
  const state = sdk.getState();

  // Eat food if HP low
  const currentHp = state.player?.hitpoints;
  const maxHp = state.player?.maxHitpoints;
  if (currentHp && maxHp && currentHp < maxHp * 0.4) {
    const inv = sdk.getInventory();
    const food = inv.find(i => i.name === 'Shrimps' || i.name === 'Bread');
    if (food) {
      await bot.eatFood(food.name);
    }
  }

  // Find nearest attackable NPC (prefer close ones to avoid pathfinding)
...

// Final sprint - attack nearby NPCs as fast as possible
const endTime = Date.now() + 60000; // Extra minute just in case
let kills = 0;
while (Date.now() < endTime) {
  const state = sdk.getState();
  const npcs = state.nearbyNpcs ?? [];
  const targets = npcs
    .filter(n => n.options?.some(o => /^attack$/i.test(o)) && (n.distance ?? 999) <= 10)
    .sort((a, b) => (a.distance ?? 999) - (b.distance ?? 999));

  const target = targets[0];
  if (!target) {
    await new Promise(r => setTimeout(r, 300));
    continue;
  }
  const result = await bot.attackNpc(target);
  if (result?.success) kills++;
}
const finalXp = sdk.getState().skills?.find(s => s.name === 'Hitpoints')?.experience ?? 0;
return { kills, finalHpXp: finalXp };

