function log(msg: string) {
  const elapsed = ((Date.now() - startTime) / 1000).toFixed(0);
  const xp = sdk.getSkill('Mining')?.experience ?? 0;
  const xpGained = xp - startXp;
  const xphr = xpGained / ((Date.now() - startTime) / 3600000);
  console.log(`[${elapsed}s | XP:${xpGained} | ${Math.round(xphr)}/hr] ${msg}`);
}

